script:
// Pricing Center: Opportunity Create → Sales Quote (replaces Quotation)
frappe.ui.form.on('Opportunity', {
	setup(frm) {
		if (logistics.crm_sales_quote) {
			logistics.crm_sales_quote.replace_make_methods(frm);
		}
	},
	refresh(frm) {
		if (!logistics.crm_sales_quote) {
			return;
		}
		logistics.crm_sales_quote.replace_make_methods(frm);
		logistics.crm_sales_quote.replace_create_button(frm);
	}
});
